// Substitutes the {{PLACEHOLDER}} tokens in the owner's frontend-designed offer
// template (Owner Profile > Offer Email Design) with the AI-generated content and
// live profile/offer values. Deliberately NOT using an n8n "HTML" node here: that
// node parses {{ }} as n8n's own expression syntax, which would collide with and
// break these literal placeholder tokens. Falls back to the same starter layout the
// frontend ships with if the owner hasn't saved a custom design yet.
const webhookBody = $('Generate Email Webhook').item.json.body;
const ownerProfile = webhookBody.ownerProfile || {};
const offer = webhookBody.offer || {};
const gen = $('Parsed Data').item.json;

const DEFAULT_TEMPLATE = "<table cellpadding="0" cellspacing="0" border="0" width="100%" style="background-color: #f0f4f8;">
  <tr>
    <td align="center" style="padding: 20px 0;">
      <table cellpadding="0" cellspacing="0" border="0" width="600" style="background-color: #ffffff; border-radius: 12px; overflow: hidden; font-family: Arial, sans-serif;">
        <tr>
          <td align="center" style="padding: 30px 0; background-color: #1e3a8a;">
            <h1 style="color: #ffffff; font-size: 24px; margin: 0;">{{COMPANY_NAME}}</h1>
          </td>
        </tr>
        <tr>
          <td align="center" style="padding: 30px 40px 20px; background-color: #f9fafb;">
            <p style="color: #3730a3; font-size: 18px; font-weight: 600; margin: 0 0 10px;">Exclusive Offer</p>
            <h2 style="color: #1e3a8a; font-size: 40px; font-weight: 900; margin: 0;">{{DISCOUNT_PERCENTAGE}}% OFF FIRST {{OFFER_PERIOD}}</h2>
          </td>
        </tr>
        <tr>
          <td align="center" style="padding: 10px 40px;">
            <img src="{{OFFER_IMAGE_URL}}" alt="" width="520" style="display: block; max-width: 100%; border-radius: 8px;" />
          </td>
        </tr>
        <tr>
          <td style="padding: 30px 40px 10px; font-size: 15px; line-height: 24px; color: #374151;">
            {{BODY}}
          </td>
        </tr>
        <tr>
          <td style="padding: 0 20px 30px;">{{SERVICES}}</td>
        </tr>
        <tr>
          <td style="padding: 0 40px 20px; font-size: 15px; line-height: 24px; color: #374151;">
            {{SIGNATURE}}
          </td>
        </tr>
        <tr>
          <td align="center" style="background-color: #1e3a8a; padding: 20px; font-family: Arial, sans-serif;">
            <a href="{{UNSUBSCRIBE_URL}}" style="color: #93c5fd; font-size: 11px;">Unsubscribe</a>
          </td>
        </tr>
      </table>
    </td>
  </tr>
</table>";

const template = ownerProfile.offerTemplateHtml || DEFAULT_TEMPLATE;

const unsubscribeUrl = 'https://api.myn8n.au/api/public/unsubscribe?businessId=' + gen.businessId;

const replacements = {
  '{{COMPANY_NAME}}': ownerProfile.companyName || '',
  '{{DISCOUNT_PERCENTAGE}}': gen.DiscountPercentage || '',
  '{{OFFER_PERIOD}}': gen.offerPeriod || '',
  '{{OFFER_IMAGE_URL}}': offer.imageUrl || '',
  '{{BODY}}': gen.body || '',
  '{{SERVICES}}': gen.servicesHtml || '',
  '{{SIGNATURE}}': ownerProfile.signatureHtml || '',
  '{{UNSUBSCRIBE_URL}}': unsubscribeUrl,
};

let html = template;
for (const [token, value] of Object.entries(replacements)) {
  html = html.split(token).join(value);
}

return [{ json: { html } }];

// Substitutes the {{PLACEHOLDER}} tokens in the owner's frontend-designed intro
// template (Owner Profile > Intro Email Design) with the AI-generated content and
// live profile values. Deliberately NOT using an n8n "HTML" node here: that node
// parses {{ }} as n8n's own expression syntax, which would collide with and break
// these literal placeholder tokens. Falls back to the same starter layout the
// frontend ships with if the owner hasn't saved a custom design yet.
const webhookBody = $('Generate Email Webhook').item.json.body;
const ownerProfile = webhookBody.ownerProfile || {};
const gen = $('Parsing Data').item.json;

const DEFAULT_TEMPLATE = "<table cellpadding="0" cellspacing="0" border="0" width="100%" style="background-color: #f4f4f4;">
  <tr>
    <td align="center" style="padding: 20px 0;">
      <table cellpadding="0" cellspacing="0" border="0" width="600" style="background-color: #ffffff; border-radius: 8px; overflow: hidden; font-family: Arial, sans-serif;">
        <tr>
          <td align="center" style="padding: 20px;">
            <img src="{{LOGO_URL}}" alt="{{COMPANY_NAME}}" width="150" style="display: block; max-width: 150px;" />
          </td>
        </tr>
        <tr>
          <td style="padding: 0 20px;"><hr style="border: 0; height: 1px; background-color: #e0e0e0;" /></td>
        </tr>
        <tr>
          <td align="center" style="padding: 10px 20px;">
            <img src="{{HERO_IMAGE_URL}}" alt="" width="560" style="display: block; max-width: 100%; border-radius: 8px;" />
          </td>
        </tr>
        <tr>
          <td style="padding: 20px 40px 10px; font-size: 15px; line-height: 24px; color: #333333;">
            {{BODY}}
            <p style="margin: 20px 0 10px;">{{SERVICES_INTRO}}</p>
          </td>
        </tr>
        <tr>
          <td style="padding: 0 20px 20px;">{{SERVICES}}</td>
        </tr>
        <tr>
          <td style="padding: 0 40px 20px; font-size: 15px; line-height: 24px; color: #333333;">
            {{SIGNATURE}}
          </td>
        </tr>
        <tr>
          <td align="center" style="background-color: #3f51b5; padding: 16px; font-family: Arial, sans-serif;">
            <a href="{{UNSUBSCRIBE_URL}}" style="color: #bbdefb; font-size: 12px; text-decoration: underline;">Unsubscribe</a>
          </td>
        </tr>
      </table>
    </td>
  </tr>
</table>";

const template = ownerProfile.introTemplateHtml || DEFAULT_TEMPLATE;

const unsubscribeUrl = 'https://api.myn8n.au/api/public/unsubscribe?businessId=' + gen.businessId;

const replacements = {
  '{{COMPANY_NAME}}': ownerProfile.companyName || '',
  '{{LOGO_URL}}': ownerProfile.logoUrl || '',
  '{{HERO_IMAGE_URL}}': ownerProfile.heroImageUrl || '',
  '{{PREHEADER}}': gen.preheader || '',
  '{{BODY}}': gen.body || '',
  '{{SERVICES_INTRO}}': gen.servicesIntro || '',
  '{{SERVICES}}': gen.servicesHtml || '',
  '{{SIGNATURE}}': ownerProfile.signatureHtml || '',
  '{{UNSUBSCRIBE_URL}}': unsubscribeUrl,
};

let html = template;
for (const [token, value] of Object.entries(replacements)) {
  html = html.split(token).join(value);
}

return [{ json: { html } }];
